// MfaDump: reads a Clickteam Fusion project (.mfa) through Nebula.Core (read-only) and writes the
// objects, values and events of every frame to a text file.
// Usage: MfaDump [--lang en|fr] <file.mfa> [output.txt]
//        MfaDump [--lang en|fr] <a.mfa> <b.mfa> ...   (or drag and drop .mfa files on the exe)
// Language: --lang, else the MFADUMP_LANG variable, else the Windows display language (fr or en).
// In French, conditions and actions use the French editor's labels (embedded table lang.fr.json,
// generated by src/bible/generate.js); a line without a safe translation stays in English.
using System.Diagnostics;
using System.Globalization;
using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Nebula;
using Nebula.Core.Data.Chunks.FrameChunks;
using Nebula.Core.Data.Chunks.FrameChunks.Events;
using Nebula.Core.Data.Chunks.FrameChunks.Events.Parameters;
using Nebula.Core.Data.Chunks.MFAChunks;
using Nebula.Core.Data.Chunks.MFAChunks.MFAObjectChunks;
using Nebula.Core.Data.Chunks.ObjectChunks;
using Nebula.Core.Data.Chunks.ObjectChunks.ObjectCommon;
using Nebula.Core.Data.PackageReaders;
using Nebula.Core.FileReaders;
using Nebula.Core.Memory;
using FAction = Nebula.Core.Data.Chunks.FrameChunks.Events.Action;

// Started from Explorer (double click, drag and drop): the console was just created, so wait for a
// key before closing it, to keep the message readable.
bool ownConsole = !Console.IsOutputRedirected && Console.CursorLeft == 0 && Console.CursorTop == 0;

// --lang option (anywhere on the command line)
var files = new List<string>();
string lang = Environment.GetEnvironmentVariable("MFADUMP_LANG")
              ?? (CultureInfo.CurrentUICulture.TwoLetterISOLanguageName == "fr" ? "fr" : "en");
for (int i = 0; i < args.Length; i++)
{
    if (args[i] == "--lang" && i + 1 < args.Length)
        lang = args[++i].ToLowerInvariant();
    else
        files.Add(args[i]);
}
L.Lang = lang == "fr" ? "fr" : "en";

if (files.Count < 1)
{
    Console.WriteLine("MfaDump: exports the events of a Clickteam Fusion project (.mfa) as text.");
    Console.WriteLine("Usage: MfaDump [--lang en|fr] <file.mfa> [output.txt]");
    Console.WriteLine("       MfaDump [--lang en|fr] <a.mfa> <b.mfa> ...   (or drag and drop .mfa files on MfaDump.exe)");
    Console.WriteLine("The .mfa file is never modified. Default output: <project>.events.txt next to the .mfa.");
    return Exit(1);
}

// Several .mfa files: Nebula keeps global state, so run one process per file
if (files.Count > 1 && files.All(a => a.EndsWith(".mfa", StringComparison.OrdinalIgnoreCase)))
{
    int failures = 0;
    foreach (string file in files)
    {
        var psi = new ProcessStartInfo(Environment.ProcessPath!) { UseShellExecute = false };
        psi.ArgumentList.Add("--lang");
        psi.ArgumentList.Add(L.Lang);
        psi.ArgumentList.Add(file);
        using var child = Process.Start(psi)!;
        child.WaitForExit();
        if (child.ExitCode != 0)
            failures++;
    }
    return Exit(failures == 0 ? 0 : 1);
}

string input = Path.GetFullPath(files[0]);
string output = files.Count > 1 ? Path.GetFullPath(files[1]) : Path.ChangeExtension(input, ".events.txt");

try
{
    Run(input, output);
    Console.WriteLine($"OK -> {output}");
    return Exit(0);
}
catch (Exception ex)
{
    Console.WriteLine($"ERROR on {input}: {ex.Message}");
    Console.WriteLine(ex.StackTrace);
    return Exit(1);
}

int Exit(int code)
{
    if (ownConsole)
    {
        Console.WriteLine("Press any key to close...");
        Console.ReadKey(true);
    }
    return code;
}

static void Run(string input, string output)
{
    // Nebula loads zlibwapi.dll and writes its logs relative to the current folder
    Directory.SetCurrentDirectory(AppContext.BaseDirectory);
    NebulaCore.Init();

    var reader = new MFAFileReader();
    NebulaCore.CurrentReader = reader;
    NebulaCore.FilePath = input;
    // Read-only: load everything in memory instead of opening the file read-write like Nebula does
    using (var bytes = new ByteReader(File.ReadAllBytes(input)))
        reader.LoadGame(bytes, input);

    MFAPackageData pkg = reader.Package;
    Out.Extensions = pkg.Extensions.Exts.ToDictionary(e => e.Key, e => (e.Value.Name, Path.GetFileNameWithoutExtension(e.Value.FileName)));
    var sb = new StringBuilder();

    sb.AppendLine($"{L.T("Application")}: {pkg.AppName}  (Fusion build {pkg.ProductBuild})");
    sb.AppendLine($"{L.T("Window")}: {pkg.AppHeader.AppWidth}x{pkg.AppHeader.AppHeight}, {pkg.AppHeader.FrameRate} FPS");
    sb.AppendLine();

    // MFADUMP_JSONL=1: also writes <output>.jsonl, one line per condition/action (statistics)
    if (Environment.GetEnvironmentVariable("MFADUMP_JSONL") == "1")
        Out.Jsonl = new StreamWriter(Path.ChangeExtension(output, ".jsonl"), false, new UTF8Encoding(false));

    DumpNames(sb, L.T("Global values"), pkg.GlobalValueNames.Names);
    DumpNames(sb, L.T("Global strings"), pkg.GlobalStringNames.Names);

    if (pkg.GlobalEvents.Events.Count > 0)
    {
        sb.AppendLine($"################ {L.T("GLOBAL EVENTS")} ################");
        Out.Frame = "(global)";
        CollectNames(pkg.GlobalEvents, pkg.FrameItems.Items);
        DumpEvents(sb, pkg.GlobalEvents);
    }

    foreach (Frame frame in pkg.Frames)
    {
        sb.AppendLine($"################ FRAME: {frame.FrameName} ################");
        sb.AppendLine();
        Out.Frame = frame.FrameName;
        Names.FlagsByItem.Clear(); // object numbers are specific to each frame
        sb.AppendLine($"== {L.T("Objects")} ==");
        foreach (MFAObjectInfo oi in frame.MFAFrameInfo.Objects)
        {
            sb.Append($"  {oi.Name} ({TypeName(oi.ObjectType)})");
            if (oi.ObjectLoader is MFAObjectLoader loader)
            {
                var vals = loader.AlterableValues;
                var named = vals.Names
                    .Select((n, i) => (n, i)).Where(x => !string.IsNullOrEmpty(x.n))
                    .Select(x => $"{x.n}={vals.AlterableValues.ElementAtOrDefault(x.i)}");
                if (named.Any())
                    sb.Append($"  {L.T("values")}: " + string.Join(", ", named));
            }
            sb.AppendLine();
            if (oi.AltFlags != null)
                Names.FlagsByItem[oi.Handle] = oi.AltFlags.AlterableFlags.Select(f => f.Name).ToArray();
        }
        sb.AppendLine();

        var qualifiers = CollectNames(frame.FrameEvents, frame.MFAItems);
        if (qualifiers.Count > 0)
        {
            sb.AppendLine($"== {L.T("Object groups (qualifiers)")} ==");
            foreach (var q in qualifiers)
                sb.AppendLine($"  {q.Key}: {(q.Value.Count > 0 ? string.Join(", ", q.Value) : "?")}");
            sb.AppendLine();
        }

        sb.AppendLine($"== {L.T("Events")} ==");
        DumpEvents(sb, frame.FrameEvents);
    }

    File.WriteAllText(output, sb.ToString(), new UTF8Encoding(true));
    Out.Jsonl?.Dispose();
}

// Prepares flag and value names per EventObject (object or qualifier), for display.
// A qualifier takes the names of its first member. Returns the members of each qualifier.
static Dictionary<string, List<string>> CollectNames(FrameEvents evts, Dictionary<int, ObjectInfo> items)
{
    var qualifiers = new Dictionary<string, List<string>>();
    Names.FlagsByEventObject.Clear();
    Names.ValuesByEventObject.Clear();
    if (evts == null)
        return qualifiers;

    foreach (EventObject eo in evts.EventObjects.Values)
    {
        ObjectInfo real = null;
        if (eo.ObjectType == 1)
            items.TryGetValue((int)eo.ItemHandle, out real);
        else if (eo.ObjectType == 3)
        {
            int qid = eo.SystemQualifier & 0x7FFF;
            var members = items.Values
                .Where(o => o.Properties is ObjectCommon oc && oc.Qualifiers.Any(q => q != -1 && (q & 0x7FFF) == qid))
                .ToList();
            qualifiers[eo.Name] = members.Select(m => m.Name).ToList();
            real = members.FirstOrDefault();
        }
        if (real != null && Names.FlagsByItem.TryGetValue(real.Header.Handle, out var flags))
            Names.FlagsByEventObject[eo.Handle] = flags;
        if (real?.Properties is ObjectCommon common)
        {
            Names.ValuesByEventObject[eo.Handle] = common.ObjectAlterableValues.Names;
            Names.ValuesByObjectName[eo.Name] = common.ObjectAlterableValues.Names;
        }
    }
    return qualifiers;
}

static void DumpNames(StringBuilder sb, string title, string[] names)
{
    if (names == null || !names.Any(n => !string.IsNullOrEmpty(n)))
        return;
    sb.AppendLine($"== {title} ==");
    for (int i = 0; i < names.Length; i++)
        if (!string.IsNullOrEmpty(names[i]))
            sb.AppendLine($"  {i}: {names[i]}");
    sb.AppendLine();
}

static void DumpEvents(StringBuilder sb, FrameEvents evts)
{
    if (evts == null || evts.Events.Count == 0)
    {
        sb.AppendLine($"  {L.T("(none)")}");
        sb.AppendLine();
        return;
    }

    string rawCode = Environment.GetEnvironmentVariable("MFADUMP_RAW");
    int indent = 0;
    int n = 0;
    foreach (Event evt in evts.Events)
    {
        n++;
        Condition first = evt.Conditions.FirstOrDefault();
        string pad() => new string(' ', 2 + indent * 4);

        // Group start
        if (IsSys(first, -10) && first.Parameters.FirstOrDefault()?.Data is ParameterGroup group)
        {
            string state = group.GroupFlags["InactiveOnStart"] ? $"  ({L.T("disabled at start")})" : "";
            sb.AppendLine($"{pad()}=== {L.T("GROUP")} “{group.Name}” ==={state}");
            indent++;
            continue;
        }
        // Group end
        if (IsSys(first, -11))
        {
            indent = Math.Max(0, indent - 1);
            sb.AppendLine($"{pad()}=== {L.T("end of group")} ===");
            sb.AppendLine();
            continue;
        }
        // Comment
        if (IsSys(first, -9) && first.Parameters.FirstOrDefault()?.Data is ParameterComment comment)
        {
            foreach (string line in comment.ToString().Replace("\r", "").Split('\n'))
                sb.AppendLine($"{pad()}// {line}");
            continue;
        }

        string flags = evt.EventFlags["Inactive"] ? $"  [{L.T("DISABLED")}]" : "";
        sb.AppendLine($"{pad()}#{n}{flags}");
        foreach (Condition c in evt.Conditions)
        {
            string en = WithNames(c, Safe(() => c.ToString(), c.ObjectType, c.Num));
            sb.AppendLine($"{pad()}  {L.T("IF"),-5} {(L.Lang == "en" ? en : WithNames(c, Tr.Condition(c, en)))}");
            Out.Record("C", n, c, en);
            // Debug: MFADUMP_RAW=<code> shows the parameters (and their raw bytes) of conditions and actions having this code
            if (rawCode != null && c.Parameters.Any(p => p.Code.ToString() == rawCode))
                foreach (var p in c.Parameters)
                    sb.AppendLine($"{pad()}        RAW[{p.Code}] {p.Data?.GetType().Name} = {Safe(() => p.ToString(), 0, 0)} | {Convert.ToHexString(p.Raw)}");
        }
        foreach (FAction a in evt.Actions)
        {
            if (a.ObjectType == -1 && a.Num == 0)
                continue; // empty action inserted by Fusion
            string en = WithNames(a, Safe(() => a.ToString(), a.ObjectType, a.Num));
            sb.AppendLine($"{pad()}  {L.T("DO"),-5} {(L.Lang == "en" ? en : WithNames(a, Tr.Action(a, en)))}");
            Out.Record("A", n, a, en);
            if (rawCode != null && a.Parameters.Any(p => p.Code.ToString() == rawCode))
                foreach (var p in a.Parameters)
                    sb.AppendLine($"{pad()}        RAW[{p.Code}] {p.Data?.GetType().Name} = {Safe(() => p.ToString(), 0, 0)} | {Convert.ToHexString(p.Raw)}");
        }
    }
    sb.AppendLine();
}

static bool IsSys(Condition c, int num) => c != null && c.ObjectType == -1 && c.Num == num;

// Readable names: Alterable Value F("Obj") -> testPosY("Obj"); Alterable Value A (of the object of
// the condition/action) -> rotation; Flag N / drapeau N -> with «name»
static string WithNames(ACEventBase x, string text)
{
    text = Regex.Replace(text, @"Alterable Value ([A-Z])\(""([^""]+)""\)", m =>
    {
        int i = m.Groups[1].Value[0] - 'A';
        return Names.ValuesByObjectName.TryGetValue(m.Groups[2].Value, out var vn) && i < vn.Length && !string.IsNullOrEmpty(vn[i])
            ? $"{vn[i]}(\"{m.Groups[2].Value}\")" : m.Value;
    });

    if (x.ObjectType < 0)
        return text;

    if (Names.ValuesByEventObject.TryGetValue(x.ObjectInfo, out var values))
        text = Regex.Replace(text, @"Alterable Value ([A-Z])(?![A-Z(])", m =>
        {
            int i = m.Groups[1].Value[0] - 'A';
            return i < values.Length && !string.IsNullOrEmpty(values[i]) ? values[i] : m.Value;
        });

    if (Names.FlagsByEventObject.TryGetValue(x.ObjectInfo, out var flags))
        text = Regex.Replace(text, @"(Flag|drapeau) (\d+)(?! «)", m =>
        {
            int i = int.Parse(m.Groups[2].Value);
            return i < flags.Length && !string.IsNullOrEmpty(flags[i]) ? $"{m.Groups[1].Value} {i} «{flags[i]}»" : m.Value;
        });
    return text;
}

static string Safe(Func<string> f, short type, short num)
{
    try { return f(); }
    catch (Exception ex) { return $"[?? type {type}, num {num} : {ex.GetType().Name}]"; }
}

static string TypeName(int t) => t switch
{
    0 => "Quick Backdrop",
    1 => "Backdrop",
    2 => "Active",
    3 => "String",
    4 => "Question",
    5 => "Score",
    6 => "Lives",
    7 => "Counter",
    8 => "Formatted Text",
    9 => "Sub-Application",
    _ => $"Extension {t}"
};

// Interface strings of the export
static class L
{
    public static string Lang = "en";
    static readonly Dictionary<string, string> Fr = new()
    {
        ["Application"] = "Application", ["Window"] = "Fenêtre", ["Global values"] = "Valeurs globales",
        ["Global strings"] = "Chaînes globales", ["GLOBAL EVENTS"] = "ÉVÉNEMENTS GLOBAUX", ["Objects"] = "Objets",
        ["values"] = "valeurs", ["Object groups (qualifiers)"] = "Groupes d'objets (qualifiers)",
        ["Events"] = "Événements", ["(none)"] = "(aucun)", ["disabled at start"] = "désactivé au démarrage",
        ["GROUP"] = "GROUPE", ["end of group"] = "fin de groupe", ["DISABLED"] = "DÉSACTIVÉ",
        ["IF"] = "SI", ["DO"] = "FAIRE",
    };
    public static string T(string en) => Lang == "fr" && Fr.TryGetValue(en, out var fr) ? fr : en;
}

// Translation of conditions and actions from the embedded table (see src/bible/generate.js):
// templates with placeholders filled from the event's parameters. Any placeholder that cannot be
// rendered safely keeps the English line.
static class Tr
{
    // Built-in: (EN template, FR template) variants; extensions: FR template
    static readonly Dictionary<string, List<(string en, string fr)>> Builtin = new();
    static readonly Dictionary<string, string> Ext = new();
    // Parameter codes of compared values: 23 = number comparison, 46 = string comparison
    static readonly int[] ComparisonCodes = { 23, 46 };
    // Headers that Nebula puts in front of actions of system objects
    static readonly Dictionary<string, string> Headers = new()
    {
        ["Special : "] = "Spécial : ", ["Sound : "] = "Son : ", ["New Objects : "] = "Nouveaux objets : ",
        ["storyboard controls : "] = "Contrôles du storyboard : ", ["the timer : "] = "Chronomètre : ",
        ["The mouse pointer and keyboard : "] = "Souris et clavier : ",
    };

    static Tr()
    {
        using var s = Assembly.GetExecutingAssembly().GetManifestResourceStream("lang.fr.json");
        if (s == null)
            return;
        using var doc = JsonDocument.Parse(s);
        foreach (var p in doc.RootElement.GetProperty("builtin").EnumerateObject())
            Builtin[p.Name] = p.Value.EnumerateArray().Select(pair => (pair[0].GetString(), pair[1].GetString())).ToList();
        foreach (var p in doc.RootElement.GetProperty("ext").EnumerateObject()) Ext[p.Name] = p.Value.GetString();
    }

    public static string Condition(Condition c, string en) => Translate(c, "C", en, "", "");

    public static string Action(FAction a, string en)
    {
        // Nebula writes "<object or system header> : <text>" for actions: keep the object name,
        // translate the system headers
        string head = "", prefix = "";
        string objName = null;
        try { objName = a.ObjectType >= 0 ? a.GetObjectName() : null; } catch { }
        int sep = en.IndexOf(" : ", StringComparison.Ordinal);
        if (objName != null && en.StartsWith(objName + " : ", StringComparison.Ordinal))
            head = prefix = objName + " : ";
        else if (sep >= 0)
        {
            head = en[..(sep + 3)];
            var player = Regex.Match(head, @"^Player (\d+) : $");
            prefix = player.Success ? $"Joueur {player.Groups[1].Value} : "
                   : Headers.TryGetValue(head, out var frHead) ? frHead : head;
        }
        return Translate(a, "A", en, head, prefix);
    }

    // enHead: header of Nebula's action text ("Obj : ", "Sound : "...), prefix: its French version
    static string Translate(ACEventBase x, string kind, string en, string enHead, string prefix)
    {
        bool negated = x is Condition c && c.OtherFlags["Negated"];
        // Nebula's text without the header / "NOT ", to match the EN templates against
        string body = en[enHead.Length..];
        if (negated && body.StartsWith("NOT "))
            body = body[4..];

        var candidates = new List<(string en, string fr)>();
        // Extension objects: their own conditions/actions from -81 / 80; below, the common ones of all objects
        if (x.ObjectType >= 32 && (kind == "A" ? x.Num >= 80 : x.Num <= -81))
        {
            string file = Out.ExtFile(x.ObjectType);
            if (file != null && Ext.TryGetValue($"ext|{file.ToLowerInvariant()}|{kind}|{x.Num}", out var t))
                candidates.Add((null, t));
        }
        else if (Builtin.TryGetValue($"{kind}|{x.ObjectType}|{x.Num}", out var pairs)
                 || x.ObjectType >= 0 && Builtin.TryGetValue($"{kind}|*|{x.Num}", out pairs))
            candidates.AddRange(pairs);

        // 1. The EN template matches Nebula's text: placeholders take the captured text
        foreach (var (enT, frT) in candidates.Where(p => p.en != null))
        {
            try
            {
                var captured = Capture(x, enT, body);
                if (captured != null)
                    return Finish(Fill(x, enT, frT, captured), prefix, negated);
            }
            catch { }
        }
        // 2. Otherwise, render the placeholders from the parameters (first candidate)
        if (candidates.Count == 0 || x.Parameters.Any(p => p.Code == 72))
            return en;
        try { return Finish(Fill(x, candidates[0].en, candidates[0].fr, null), prefix, negated); }
        catch { return en; }
    }

    static string Finish(string fr, string prefix, bool negated) => prefix + (negated ? "NON " : "") + fr;

    // Placeholder values of an EN template matched against Nebula's text, or null if it does not match
    static Dictionary<string, string> Capture(ACEventBase x, string enTemplate, string text)
    {
        var names = new List<string>();
        var parts = Regex.Split(enTemplate, @"(<[^<>]+>)");
        var sb = new StringBuilder("^");
        string objName = null;
        foreach (string part in parts)
        {
            if (part.Length > 2 && part[0] == '<' && part[^1] == '>')
            {
                names.Add(part[1..^1]);
                // Known values (object names can contain spaces) keep the match unambiguous
                if (part == "<object>" && (objName ??= x.GetObjectName()) != null)
                    sb.Append($"({Regex.Escape(objName)})");
                else if (part == "<op>")
                    sb.Append("(=|<>|<=|<|>=|>)");
                else
                    sb.Append("(.*?)");
            }
            else
                sb.Append(Regex.Escape(part));
        }
        var m = Regex.Match(text, sb.Append('$').ToString(), RegexOptions.Singleline);
        if (!m.Success)
            return null;
        var values = new Dictionary<string, string>();
        for (int i = 0; i < names.Count; i++)
            values.TryAdd(names[i], m.Groups[i + 1].Value);
        return values;
    }

    // Placeholders rendered in French from the parameters even when captured (the EN text is English)
    static readonly HashSet<string> FrenchRendered = new() { "mouse button", "joystick direction", "player no.", "object" };

    static string Fill(ACEventBase x, string enTemplate, string frTemplate, Dictionary<string, string> captured)
    {
        bool hasOp = frTemplate.Contains("<op>");
        return Regex.Replace(frTemplate, @"<([^<>]+)>", m =>
        {
            string name = m.Groups[1].Value;
            if (captured != null && !FrenchRendered.Contains(name) && captured.TryGetValue(name, out var v))
            {
                // French labels include the operator in the compared parameter: "<op> <p1>" in EN, "<p1>" in FR
                if (!hasOp && captured.TryGetValue("op", out var op) && enTemplate.Contains($"<op> <{name}>"))
                    v = $"{op} {v}";
                return v;
            }
            return Placeholder(x, name, frTemplate, m.Index, hasOp) ?? throw new FormatException(m.Value);
        });
    }

    // Value of one placeholder, or null when it cannot be rendered safely
    static string Placeholder(ACEventBase x, string name, string template, int at, bool hasOp)
    {
        Parameter P(int i) => i < x.Parameters.Length ? x.Parameters[i] : throw new IndexOutOfRangeException();
        var m = Regex.Match(name, @"^(?:(alterable value|alterable string|global value|global string|zone) )?p(\d+)$");
        if (m.Success)
        {
            int i = int.Parse(m.Groups[2].Value);
            return m.Groups[1].Value switch
            {
                "alterable value" => x.GetObjectAlterableValueName(P(i).Data),
                "alterable string" => x.GetObjectAlterableStringName(P(i).Data),
                "global value" => x.GetGlobalValueName(P(i).Data),
                "global string" => x.GetGlobalStringName(P(i).Data),
                "zone" => x.GetZone(i),
                _ => Param(x, P(i), withOperator: !hasOp),
            };
        }
        switch (name)
        {
            case "object":
                return x.GetObjectName();
            case "op":
                // Operator of the next compared parameter in the template
                var next = Regex.Match(template[at..], @"p(\d+)>");
                return next.Success && P(int.Parse(next.Groups[1].Value)).Data is ParameterExpressions pe
                    ? x.GetComparison(pe.Comparison) : null;
            case "player no.":
                return (x.ObjectInfo + 1).ToString();
            case "key":
                return x.GetKeyboardKey(((ParameterShort)P(0).Data).Value);
            case "scene":
                return P(0).Data switch
                {
                    ParameterExpressions e => e.ToString(),
                    ParameterInt v => x.GetFrameName(v.Value),
                    ParameterShort v => x.GetFrameName(v.Value),
                    _ => null
                };
            case "animation":
                return P(0).Data is ParameterShort a ? x.GetObjectAnimation(a.Value) : null;
            case "mouse button":
                return P(0).Data switch
                {
                    ParameterClick c => (c.Button switch { 1 => "du milieu", 2 => "droit", _ => "gauche" })
                                        + (c.IsDouble != 0 ? " (double-clic)" : ""),
                    ParameterShort s => s.Value switch { 2 => "droit", 4 => "du milieu", _ => "gauche" },
                    _ => null
                };
            case "joystick direction":
                return P(0).Data is ParameterShort j ? Joystick(j.Value) : null;
            default:
                return null; // <value>, <direction>, <menu option>... : keep English
        }
    }

    // Joystick test (bits: up, down, left, right, fire 1-4), like ACEventBase.GetJoystickString
    static string Joystick(short flags)
    {
        bool B(int bit) => (flags & (1 << bit)) != 0;
        var parts = new List<string>();
        var fires = Enumerable.Range(1, 4).Where(i => B(3 + i)).Select(i => $"feu {i}").ToList();
        if (fires.Count > 0)
            parts.Add("appuie sur " + string.Join("+", fires));
        string v = B(0) ? "en haut" : B(1) ? "en bas" : null;
        string h = B(2) ? "à gauche" : B(3) ? "à droite" : null;
        string move = v != null && h != null ? $"{v} {h}" : v ?? h;
        if (move != null)
            parts.Add("déplacé " + move);
        return parts.Count > 0 ? string.Join(", ", parts) : null;
    }

    // One parameter: names of values/strings, and the comparison operator in front of a compared
    // value when the template has no <op> (French editor labels include it in the parameter)
    static string Param(ACEventBase x, Parameter p, bool withOperator)
    {
        string text = p.Code switch
        {
            50 => x.GetObjectAlterableValueName(p.Data),
            61 => x.GetObjectAlterableStringName(p.Data),
            49 => x.GetGlobalValueName(p.Data),
            58 => x.GetGlobalStringName(p.Data),
            _ => p.ToString()
        };
        if (withOperator && Array.IndexOf(ComparisonCodes, p.Code) >= 0 && p.Data is ParameterExpressions e)
            text = $"{x.GetComparison(e.Comparison)} {text}";
        return text;
    }
}

static class Out
{
    public static StreamWriter Jsonl;
    // Extension index -> (displayed name, .mfx file without extension)
    public static Dictionary<int, (string name, string file)> Extensions = new();
    public static string Frame = "";
    static readonly JsonSerializerOptions JsonOpts = new() { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    public static string ExtFile(int type) => ExtOf(type).Item2;

    // One line per condition/action ("C"/"A"), then one per item of the expressions of its parameters ("E")
    public static void Record(string kind, int ev, ACEventBase x, string text)
    {
        if (Jsonl == null)
            return;
        string obj = null;
        if (x.ObjectType >= 0)
            try { obj = x.GetObjectName(); } catch { }
        var (ext, extFile) = ExtOf(x.ObjectType);
        Write(new
        {
            frame = Frame, ev, kind, type = x.ObjectType, num = x.Num, ext, extFile, obj,
            neg = x is Condition c && c.OtherFlags["Negated"],
            pars = x.Parameters.Select(p => p.Code).ToArray(),
            text
        });
        foreach (var exprs in x.Parameters.Select(p => p.Data).OfType<ParameterExpressions>())
            foreach (var e in exprs.Expressions)
            {
                var (eExt, eFile) = ExtOf(e.ObjectType);
                string eText;
                try { eText = e.ToString(); } catch (Exception ex) { eText = $"[?? {ex.GetType().Name}]"; }
                Write(new { frame = Frame, ev, kind = "E", type = e.ObjectType, num = e.Num, ext = eExt, extFile = eFile, text = eText });
            }
    }

    static (string, string) ExtOf(int type) =>
        type >= 32 && Extensions.TryGetValue(type - 32, out var e) ? e : (null, null);

    static void Write(object o) => Jsonl.WriteLine(JsonSerializer.Serialize(o, JsonOpts));
}

static class Names
{
    public static readonly Dictionary<int, string[]> FlagsByItem = new();
    public static readonly Dictionary<int, string[]> FlagsByEventObject = new();
    public static readonly Dictionary<int, string[]> ValuesByEventObject = new();
    public static readonly Dictionary<string, string[]> ValuesByObjectName = new();
}
